type S = (number | null)[];
export function sma(values: number[], period: number): S;
export function ema(values: number[], period: number): S;
export function rsi(values: number[], period?: number): S;
export function macd(values: number[], fast?: number, slow?: number, signal?: number): { line: S; signal: S; hist: S };
export function bollinger(values: number[], period?: number, mult?: number): { mid: S; upper: S; lower: S };
export function crossUp(a: S, b: S, i: number): boolean;
export function crossDown(a: S, b: S, i: number): boolean;
type N = number[];
export function rma(values: S | N, period: number): S;
export function wma(values: N, period: number): S;
export function trueRange(H: N, L: N, C: N): N;
export function atr(H: N, L: N, C: N, period?: number): S;
export function stochastic(H: N, L: N, C: N, k?: number, smooth?: number, d?: number): { k: S; d: S };
export function stochRsi(C: N, rsiLen?: number, stochLen?: number, k?: number, d?: number): { k: S; d: S };
export function adx(H: N, L: N, C: N, len?: number): { adx: S; pdi: S; mdi: S };
export function cci(H: N, L: N, C: N, len?: number): S;
export function williamsR(H: N, L: N, C: N, len?: number): S;
export function obv(C: N, V: N): N;
export function mfi(H: N, L: N, C: N, V: N, len?: number): S;
export function vwap(H: N, L: N, C: N, V: N, key: (i: number) => string | number): S;
export function supertrend(H: N, L: N, C: N, len?: number, mult?: number): { line: S; dir: S };
export function psar(H: N, L: N, start?: number, inc?: number, max?: number): S;
export function ichimoku(H: N, L: N, C: N, conv?: number, base?: number, spanB?: number, disp?: number): { tenkan: S; kijun: S; spanA: S; spanB: S; chikou: S };
export function donchian(H: N, L: N, len?: number): { upper: S; lower: S; mid: S };
export function keltner(H: N, L: N, C: N, len?: number, mult?: number): { mid: S; upper: S; lower: S };
